Built around the actual Telegram Mini App conventions rather than treating this as a generic web screen: the host's **BackButton** drives "back to cart" and the host's **MainButton** is the Pay button, theming comes from `--tg-theme-*` CSS variables (so dark mode just works), layout respects safe-area/viewport insets, and the form triggers Telegram's closing-confirmation while dirty. A plain-DOM fallback (back link + footer button) only renders when the Telegram SDK isn't present, so the screen still works in a normal browser during development — never as a second control inside real Telegram.

**`telegram.d.ts`** — minimal ambient types for the subset of the SDK used here.

```ts
export interface TelegramWebApp {
  version: string;
  colorScheme: 'light' | 'dark';
  themeParams: Record<string, string>;
  isVersionAtLeast: (version: string) => boolean;
  enableClosingConfirmation: () => void;
  disableClosingConfirmation: () => void;
  disableVerticalSwipes: () => void;
  enableVerticalSwipes: () => void;
  setHeaderColor: (color: string) => void;
  setBackgroundColor: (color: string) => void;
  BackButton: {
    show: () => void;
    hide: () => void;
    onClick: (cb: () => void) => void;
    offClick: (cb: () => void) => void;
  };
  MainButton: {
    setText: (text: string) => void;
    setParams: (params: Partial<{
      text: string;
      color: string;
      text_color: string;
      is_active: boolean;
      is_visible: boolean;
    }>) => void;
    show: () => void;
    hide: () => void;
    enable: () => void;
    disable: () => void;
    showProgress: (leaveActive?: boolean) => void;
    hideProgress: () => void;
    onClick: (cb: () => void) => void;
    offClick: (cb: () => void) => void;
  };
  HapticFeedback?: {
    impactOccurred: (style: 'light' | 'medium' | 'heavy' | 'rigid' | 'soft') => void;
    notificationOccurred: (type: 'error' | 'success' | 'warning') => void;
    selectionChanged: () => void;
  };
}

declare global {
  interface Window {
    Telegram?: {
      WebApp: TelegramWebApp;
    };
  }
}

export {};
```

