**`CheckoutScreen.tsx`**

```tsx
import React, { useEffect, useMemo, useRef, useState } from 'react';
import './CheckoutScreen.css';
import type { CartItem, DeliveryAddress, CheckoutScreenProps } from './types';

const CURRENCY = 'USD';

function formatPrice(value: number): string {
  return new Intl.NumberFormat('en-US', { style: 'currency', currency: CURRENCY }).format(value);
}

const EMPTY_ADDRESS: DeliveryAddress = {
  fullName: '',
  phone: '',
  country: '',
  city: '',
  addressLine1: '',
  addressLine2: '',
  postalCode: '',
};

const REQUIRED_FIELDS: (keyof DeliveryAddress)[] = [
  'fullName',
  'phone',
  'country',
  'city',
  'addressLine1',
  'postalCode',
];

export default function CheckoutScreen({ items, deliveryFee = 0, onBack, onPay }: CheckoutScreenProps) {
  const [address, setAddress] = useState<DeliveryAddress>(EMPTY_ADDRESS);
  const [touched, setTouched] = useState<Partial<Record<keyof DeliveryAddress, boolean>>>({});
  const [isPaying, setIsPaying] = useState(false);
  const [payError, setPayError] = useState<string | null>(null);

  const webApp = typeof window !== 'undefined' ? window.Telegram?.WebApp : undefined;

  const subtotal = useMemo(
    () => items.reduce((sum, item) => sum + item.price * item.quantity, 0),
    [items]
  );
  const total = subtotal + deliveryFee;

  const isDirty = useMemo(
    () => Object.values(address).some((value) => value.trim().length > 0),
    [address]
  );

  const isValid = useMemo(
    () => REQUIRED_FIELDS.every((field) => address[field].trim().length > 1),
    [address]
  );

  useEffect(() => {
    if (!webApp) return;
    webApp.BackButton.show();
    webApp.BackButton.onClick(onBack);
    return () => {
      webApp.BackButton.offClick(onBack);
      webApp.BackButton.hide();
    };
  }, [webApp, onBack]);

  useEffect(() => {
    if (!webApp) return;
    if (isDirty) {
      webApp.enableClosingConfirmation();
    } else {
      webApp.disableClosingConfirmation();
    }
  }, [webApp, isDirty]);

  useEffect(() => {
    if (!webApp) return;
    if (webApp.isVersionAtLeast('6.1')) {
      webApp.setHeaderColor('secondary_bg_color');
      webApp.setBackgroundColor('bg_color');
    }
    if (webApp.isVersionAtLeast('7.7')) {
      webApp.disableVerticalSwipes();
    }
    return () => {
      if (webApp.isVersionAtLeast('7.7')) {
        webApp.enableVerticalSwipes();
      }
    };
  }, [webApp]);

  const handlePayRef = useRef<() => void>(() => {});
  handlePayRef.current = async () => {
    if (!isValid || isPaying) return;
    setPayError(null);
    setIsPaying(true);
    webApp?.MainButton.showProgress(false);
    webApp?.HapticFeedback?.impactOccurred('medium');
    try {
      await onPay(address);
      webApp?.HapticFeedback?.notificationOccurred('success');
      webApp?.disableClosingConfirmation();
    } catch (err) {
      webApp?.HapticFeedback?.notificationOccurred('error');
      setPayError(err instanceof Error ? err.message : 'Payment failed. Please try again.');
    } finally {
      setIsPaying(false);
      webApp?.MainButton.hideProgress();
    }
  };

  useEffect(() => {
    if (!webApp) return;
    const mainButton = webApp.MainButton;
    const text = `Pay ${formatPrice(total)}`;
    if (webApp.isVersionAtLeast('6.1')) {
      mainButton.setParams({ text, is_active: isValid && !isPaying, is_visible: true });
    } else {
      mainButton.setText(text);
      mainButton.show();
      if (isValid && !isPaying) {
        mainButton.enable();
      } else {
        mainButton.disable();
      }
    }
    const onClick = () => handlePayRef.current();
    mainButton.onClick(onClick);
    return () => mainButton.offClick(onClick);
  }, [webApp, total, isValid, isPaying]);

  useEffect(() => {
    return () => {
      webApp?.MainButton.hide();
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const handleChange = (field: keyof DeliveryAddress) => (
    event: React.ChangeEvent<HTMLInputElement>
  ) => {
    setAddress((prev) => ({ ...prev, [field]: event.target.value }));
  };

  const handleBlur = (field: keyof DeliveryAddress) => () => {
    setTouched((prev) => ({ ...prev, [field]: true }));
  };

  const fieldError = (field: keyof DeliveryAddress): string | undefined => {
    if (!touched[field]) return undefined;
    if (REQUIRED_FIELDS.includes(field) && address[field].trim().length <= 1) {
      return 'Required';
    }
    return undefined;
  };

  return (
    <div className="checkout">
      <header className="checkout__header">
        {!webApp && (
          <button
            type="button"
            className="checkout__back"
            onClick={onBack}
            aria-label="Back to cart"
          >
            ‹ Cart
          </button>
        )}
        <h1 className="checkout__title">Checkout</h1>
      </header>

      <section className="checkout__section" aria-labelledby="cart-heading">
        <h2 id="cart-heading" className="checkout__section-title">Your order</h2>
        <ul className="checkout__items">
          {items.map((item) => (
            <li key={item.id} className="checkout__item">
              {item.imageUrl && (
                <img src={item.imageUrl} alt="" className="checkout__item-image" />
              )}
              <div className="checkout__item-info">
                <span className="checkout__item-name">{item.name}</span>
                <span className="checkout__item-qty">Qty {item.quantity}</span>
              </div>
              <span className="checkout__item-price">
                {formatPrice(item.price * item.quantity)}
              </span>
            </li>
          ))}
        </ul>

        <dl className="checkout__totals">
          <div className="checkout__totals-row">
            <dt>Subtotal</dt>
            <dd>{formatPrice(subtotal)}</dd>
          </div>
          <div className="checkout__totals-row">
            <dt>Delivery</dt>
            <dd>{deliveryFee > 0 ? formatPrice(deliveryFee) : 'Free'}</dd>
          </div>
          <div className="checkout__totals-row checkout__totals-row--total">
            <dt>Total</dt>
            <dd>{formatPrice(total)}</dd>
          </div>
        </dl>
      </section>

      <section className="checkout__section" aria-labelledby="address-heading">
        <h2 id="address-heading" className="checkout__section-title">Delivery address</h2>
        <form className="checkout__form" onSubmit={(e) => e.preventDefault()}>
          <label className="checkout__field">
            <span className="checkout__label">Full name</span>
            <input
              className="checkout__input"
              type="text"
              name="fullName"
              autoComplete="name"
              value={address.fullName}
              onChange={handleChange('fullName')}
              onBlur={handleBlur('fullName')}
            />
            {fieldError('fullName') && <span className="checkout__error">{fieldError('fullName')}</span>}
          </label>

          <label className="checkout__field">
            <span className="checkout__label">Phone number</span>
            <input
              className="checkout__input"
              type="tel"
              name="phone"
              autoComplete="tel"
              value={address.phone}
              onChange={handleChange('phone')}
              onBlur={handleBlur('phone')}
            />
            {fieldError('phone') && <span className="checkout__error">{fieldError('phone')}</span>}
          </label>

          <label className="checkout__field">
            <span className="checkout__label">Country</span>
            <input
              className="checkout__input"
              type="text"
              name="country"
              autoComplete="country-name"
              value={address.country}
              onChange={handleChange('country')}
              onBlur={handleBlur('country')}
            />
            {fieldError('country') && <span className="checkout__error">{fieldError('country')}</span>}
          </label>

          <label className="checkout__field">
            <span className="checkout__label">City</span>
            <input
              className="checkout__input"
              type="text"
              name="city"
              autoComplete="address-level2"
              value={address.city}
              onChange={handleChange('city')}
              onBlur={handleBlur('city')}
            />
            {fieldError('city') && <span className="checkout__error">{fieldError('city')}</span>}
          </label>

          <label className="checkout__field">
            <span className="checkout__label">Address line 1</span>
            <input
              className="checkout__input"
              type="text"
              name="addressLine1"
              autoComplete="address-line1"
              value={address.addressLine1}
              onChange={handleChange('addressLine1')}
              onBlur={handleBlur('addressLine1')}
            />
            {fieldError('addressLine1') && <span className="checkout__error">{fieldError('addressLine1')}</span>}
          </label>

          <label className="checkout__field">
            <span className="checkout__label">Address line 2 (optional)</span>
            <input
              className="checkout__input"
              type="text"
              name="addressLine2"
              autoComplete="address-line2"
              value={address.addressLine2}
              onChange={handleChange('addressLine2')}
            />
          </label>

          <label className="checkout__field">
            <span className="checkout__label">Postal code</span>
            <input
              className="checkout__input"
              type="text"
              name="postalCode"
              autoComplete="postal-code"
              value={address.postalCode}
              onChange={handleChange('postalCode')}
              onBlur={handleBlur('postalCode')}
            />
            {fieldError('postalCode') && <span className="checkout__error">{fieldError('postalCode')}</span>}
          </label>
        </form>
      </section>

      {payError && <p className="checkout__pay-error" role="alert">{payError}</p>}

      {!webApp && (
        <button
          type="button"
          className="checkout__pay-button"
          disabled={!isValid || isPaying}
          onClick={() => handlePayRef.current()}
        >
          {isPaying ? 'Processing…' : `Pay ${formatPrice(total)}`}
        </button>
      )}
    </div>
  );
}
```

**`CheckoutScreen.css`**

