  --space-2: 8px;
  --space-3: 12px;
  --space-4: 16px;
  min-height: var(--tg-viewport-stable-height, 100vh);
  box-sizing: border-box;
  padding-top: calc(var(--tg-safe-area-inset-top, 0px) + var(--tg-content-safe-area-inset-top, 0px) + var(--space-3));
  padding-right: calc(var(--tg-safe-area-inset-right, 0px) + var(--space-4));
  padding-bottom: calc(var(--tg-safe-area-inset-bottom, 0px) + 100px);
